def skjkasdkd(lst):
    def is_prime(n: int) -> bool:
        if n < 2:
            return False
        if n == 2:
            return True
        if n % 2 == 0:
            return False
        i = 3
        while i * i <= n:
            if n % i == 0:
                return False
            i += 2
        return True

    def sum_digits(n: int) -> int:
        s = str(abs(n))  # handle negative numbers just in case (though primes are positive here)
        return sum(int(d) for d in s)

    max_prime = None
    for num in lst:
        if is_prime(num):
            if max_prime is None or num > max_prime:
                max_prime = num

    # If no prime was found, define behavior (based on examples, there's always at least one prime)
    return sum_digits(max_prime) if max_prime else 0


